// DecodeWorldTilemap_c: computes a tilemap coordinate from $AB direction bit,
// $06FA index, and $070A base, then dispatches to the appropriate world-map
// decoder (overworld, underground, or moon) based on $1700.
//
// Assumptions (inherited from caller, typical field-module convention):
//   mf=1 (8-bit A), xf=0 (16-bit X/Y), DB=0x7E, DP=0, B=0.
//   The first `lda $ab / and #$01 / bne @fd26` is a no-op branch to the
//   very next instruction and is omitted.

// WorldSizeMask is a data table in WRAM at $7E:00B0 (offset 0xB0).
// FIXME: verify this offset from the ca65-bridge label dump.
#define WORLD_SIZE_MASK_OFFSET 0xB0

void DecodeWorldTilemap_c(Snes *snes) {
    uint8_t *ram = snes->ram;

    // @fd26: lda $06fa / tax  (X = zero-extended index; Pitfall 9 – B=0 assumed)
    uint16_t x = ram[0x06FA];

    // lda $ab / and #$02 / bne @fd3c
    uint8_t ab = ram[0xAB];
    uint8_t val;
    if (ab & 0x02) {
        // @fd3c: lda $070a / clc / adc #$20 / and WorldSizeMask,x
        val = (uint8_t)(ram[0x070A] + 0x20);          // Pitfall 7 – 8-bit truncation
        uint8_t mask = ram[WORLD_SIZE_MASK_OFFSET + x];
        val &= mask;
    } else {
        // lda $070a / sec / sbc #$1f / and WorldSizeMask,x
        val = (uint8_t)(ram[0x070A] - 0x1F);          // Pitfall 7
        uint8_t mask = ram[WORLD_SIZE_MASK_OFFSET + x];
        val &= mask;
    }

    // @fd45: sta $3d / sta $93 / stz $3e / stz $44
    ram[0x3D] = val;
    ram[0x93] = val;
    ram[0x3E] = 0;
    ram[0x44] = 0;

    // lda $3d / and #$3f / sta $41 / stz $40
    ram[0x41] = val & 0x3F;
    ram[0x40] = 0;

    // asl $3d / rol $3e  → 16-bit left shift of the little-endian word at $3D-$3E
    uint16_t word = read16(ram, 0x3D);
    word <<= 1;
    write16(ram, 0x3D, word);

    // lda $1700 / bne @fd66
    uint8_t world_type = ram[0x1700];
    if (world_type == 0) {
        decode_overworld_tilemap_emu(snes);
        mod_overworld_tilemap_emu(snes);   // jsl ModOverworldTilemap
        return;
    }
    // @fd66: cmp #$01 / bne @fd6e
    if (world_type == 1) {
        decode_underground_tilemap_emu(snes);
        return;
    }
    // @fd6e: default (moon)
    decode_moon_tilemap_emu(snes);
}


